#!/usr/bin/env python3
"""Generate concise atomic vulnerability cards from reviewed source data."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def card(id, title, family, cwe, capec, aliases, surfaces, languages, frameworks, platforms, preconditions, boundaries, flow, code, config, architecture, questions, safe, false, impact, severity, exploit, remediation, *tail):
    # A few initial records predate the explicit secure_patterns field. Keep
    # generation backward-compatible while assigning a safe default.
    capec = [({"CAPEC-225": "CAPEC-115", "CAPEC-1548": "CAPEC-77"}.get(value, value)) for value in capec]
    if len(tail) == 5:
        secure, regression, refs, provenance, body = tail
    elif len(tail) == 4:
        regression, refs, provenance, body = tail
        secure = ["Use typed inputs, explicit policy checks and least-privilege boundaries."]
    else:
        raise TypeError(f"card tail must contain 4 or 5 values, got {len(tail)}")
    return {
        "id": id, "title": title, "aliases": aliases, "summary": body.split("\n", 1)[0],
        "family": family, "canonical_cwe": cwe, "related_cwe": [cwe], "capec": capec,
        "owasp_mappings": [], "asvs_mappings": [], "wstg_mappings": [], "masvs_mappings": [],
        "api_security_mappings": [], "genai_mappings": [], "applies_to": ["source code", "configuration", "architecture"],
        "surfaces": surfaces, "languages": languages, "frameworks": frameworks, "platforms": platforms,
        "preconditions": preconditions, "trust_boundaries": boundaries, "data_flow": flow,
        "code_signals": code, "configuration_signals": config, "architecture_signals": architecture,
        "audit_questions": questions, "safe_verification": safe, "false_positives": false,
        "impact": impact, "severity_factors": severity, "exploitability_factors": exploit,
        "remediation": remediation, "secure_patterns": secure, "regression_tests": regression,
        "related_vulnerabilities": [], "references": refs, "source_provenance": provenance,
        "last_reviewed": "2026-08-07", "maturity": "curated", "review_status": "reviewed", "body": body,
    }


COMMON_BOUNDS = ["untrusted principal to application", "application to data/control-plane sink"]
COMMON_SAFE = ["Use a local or staging fixture with synthetic data, test identities and a unique canary; keep egress disabled.", "Assert the expected denial or safe encoding and inspect only test output; do not use real credentials, persistence or destructive state."]
DIRECTORY_MAP = {
    "authorization-access": "authorization", "authentication-identity": "authentication",
    "browser-client": "browser", "http-proxy-cache": "http", "ssrf-network": "network",
    "files-paths-storage": "files", "serialization-parsers": "serialization",
    "business-logic-state": "business", "availability-resources": "availability",
    "information-secrets-privacy": "secrets", "crypto-transport": "crypto",
    "configuration-deployment": "configuration", "supply-chain-cicd": "supply",
    "cloud-containers-infra": "cloud", "native-memory": "native", "ai-llm-rag-agents": "ai",
    "api-protocols": "api", "internal-enterprise": "internal", "hardware-firmware-iot": "hardware",
    "web3-smart-contracts": "web3",
}

