def render(record: dict) -> str:
    body = record.pop("body")
    lines = ["---"]
    for key, value in record.items():
        lines.append(f"{key}: {json.dumps(value, ensure_ascii=False, separators=(',', ':'))}")
    lines += ["---", "", f"# {record['title']}", "", body, "", "## Audit notes", "", "Use the source/transform/control/sink model above. Report only evidence-backed flows and keep verification inside the safe boundary.", "", "## Retrieval", "", f"Canonical ID: `{record['id']}`; canonical ontology entry: `{record['canonical_cwe']}`.", ""]
    return "\n".join(lines)


def main() -> int:
    for record in CARDS:
        path = ROOT / "vulnerabilities" / DIRECTORY_MAP.get(record["family"], record["family"]) / (record["id"].split(".", 2)[-1] + ".md")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(render(record.copy()), encoding="utf-8")
    print(f"generated {len(CARDS)} atomic cards")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
